	// - "cookie:JSESSIONID" - Java/Tomcat session cookie
	// - "cookie:PHPSESSID" - PHP session cookie
	// - "cookie:ASP.NET_SessionId" - ASP.NET session
	// - "cookie:connect.sid" - Node.js/Express session
